    git(run, directory, ["rev-parse", "HEAD"]),
    git(run, directory, [
      "for-each-ref",
      "--format=%(push:remotename)%00%(push:remoteref)%00%(upstream:remotename)%00%(upstream:remoteref)",
      `refs/heads/${branch}`
