  const output = await git(run, directory, ["worktree", "list", "--porcelain"]);
  if (output === undefined)
    return;
  const entries = [];
  for (const block of output.split(/\n\s*\n/)) {
    let entry;
    for (const line of block.split(`
`)) {
      const [key, ...rest] = line.split(" ");
      const value = rest.join(" ");
