async function resolveProjects(run, directory, accepted) {
  const remoteConfig = await git(run, directory, ["config", "--get-regexp", "^remote\\..*\\.url$"]);
  if (remoteConfig === undefined)
    return { kind: "none", reason: "No Git remotes" };
  const remotes = [];
  for (const line of remoteConfig.split(`
`)) {
    const match = line.match(/^remote\.(.+)\.url\s+(.+)$/);
    if (match)
      remotes.push([match[1], match[2]]);
  }
  remotes.sort(([a], [b]) => Number(b === "origin") - Number(a === "origin"));
  const projects = [];
  for (const [, url] of remotes) {
    const project = parseRemote(url);
